const settings = require('./settings')
const command = require('./passwordCommand')
const matchesStoredKey = require('./matchesStoredKey')
const ID = /^[a-f0-9]{8}-(?:[a-f0-9]{4}-){3}[a-f0-9]{12}$/i

function failure (message = 'Bitwarden CLI operation failed; check sign-in and unlock your vault with BW_SESSION') {
  return Object.assign(new Error(message), { code: 'BITWARDEN_FAILED' })
}

function parse (value) {
  try { return JSON.parse(value) } catch { throw failure('Bitwarden CLI returned an invalid response') }
}

function location (value) {
  if (!value) return null
  const loc = parse(Buffer.from(String(value), 'base64').toString('utf8'))
  if (!loc || !ID.test(loc.item || '') || !ID.test(loc.userId || '') || typeof loc.serverUrl !== 'string') {
    throw failure('invalid Bitwarden private-key reference in dotenvx settings')
  }
  return loc
}

function checkIdentity (value, loc) {
  const status = parse(value)
  if (!status || status.status !== 'unlocked' || !ID.test(status.userId || '')) throw failure()
  if (status.userId !== loc.userId || (status.serverUrl || '') !== loc.serverUrl) {
    throw failure('Bitwarden account or server does not match the stored private-key reference')
  }
}

function verified (publicKey, value) {
  if (matchesStoredKey(publicKey, value)) return { [publicKey]: value }
  throw failure('Bitwarden private key does not match the .env public key')
}

module.exports = function bitwarden (options = {}) {
  const env = () => options.processEnv || process.env
  const disabled = () => options.noBitwarden === true || env().DOTENVX_NO_BITWARDEN === 'true'
  function cli () {
    if (!env().BW_SESSION) throw failure('Bitwarden requires an unlocked BW_SESSION; run bw login, then bw unlock --raw and set BW_SESSION')
    return command('bw', env(), failure)
  }
  return {
    async get (publicKey) {
      if (disabled()) return {}
      const loc = location(await settings.get(`DOTENVX_BITWARDEN_${publicKey}`, env()))
      if (!loc) return {}
      const read = cli().get
      checkIdentity(await read(['status', '--nointeraction']), loc)
      return verified(publicKey, await read(['get', 'password', loc.item, '--nointeraction']))
    },
    getSync (publicKey) {
      if (disabled()) return {}
      const loc = location(settings.getSync(`DOTENVX_BITWARDEN_${publicKey}`, env()))
      if (!loc) return {}
      const read = cli().getSync
      checkIdentity(read(['status', '--nointeraction']), loc)
      return verified(publicKey, read(['get', 'password', loc.item, '--nointeraction']))
    }
  }
}
